-- TNS|GateRush|TNE
-- GateRush: twin-stick FPV tunnel game for EdgeTX B&W 128x64 radios.
-- Generated by tools/build.lua from src/ - edit the sources, not this file.

local config = (function()
-- Settings: ranges, defaults, tuning tables, .cfg persistence, difficulty key.
local M = {}

M.DIR = "/SCRIPTS/TOOLS/GATERUSH/"
M.FILE = M.DIR .. "gaterush.cfg"

-- head speed in px per 50 ms tick, by SPEED 1..5
M.SPEEDS = { 0.8, 1.1, 1.5, 2.0, 2.6 }
-- growth in % per minute alive, by SPEED_ACCEL / CURVE_ACCEL 0..5 (index = value + 1)
M.ACCELS = { 0, 45, 90, 135, 180, 240 }

-- CRASH_DELAY is stored in tenths of a second so the value stays an integer.
-- diff = part of the difficulty key
M.ITEMS = {
  { key = "MARGIN", name = "MARGIN", lo = 0, hi = 5, def = 2, diff = true },
  { key = "CRASH_DELAY", name = "CRASH DELAY", lo = 0, hi = 20, def = 3, diff = true },
  { key = "SPEED", name = "SPEED", lo = 1, hi = 5, def = 3, diff = true },
  { key = "SPEED_ACCEL", name = "SPEED ACCEL", lo = 0, hi = 5, def = 2, diff = true },
  { key = "CURVE_ACCEL", name = "CURVE ACCEL", lo = 0, hi = 5, def = 2, diff = true },
  { key = "TRACK_LEN", name = "TRACK LEN", lo = 20, hi = 80, step = 5, def = 40, diff = true },
  { key = "HAPTIC", name = "HAPTIC", lo = 0, hi = 1, def = 1 },
  { key = "STICK_MODE", name = "STICK MODE", lo = 1, hi = 4, def = 2 },
}

M.v = {}

function M.defaults()
  for i = 1, #M.ITEMS do
    local it = M.ITEMS[i]
    M.v[it.key] = it.def
  end
  -- getStickMode() only exists from EdgeTX 3.0; it only seeds the default
  if getStickMode then
    local ok, mode = pcall(getStickMode)
    if ok and type(mode) == "number" and mode >= 1 and mode <= 4 then M.v.STICK_MODE = mode end
  end
end

function M.item(key)
  for i = 1, #M.ITEMS do
    if M.ITEMS[i].key == key then return M.ITEMS[i] end
  end
end

-- step the value of item it by dir (+1/-1), clamped
function M.change(it, dir)
  local nv = M.v[it.key] + dir * (it.step or 1)
  if nv < it.lo then nv = it.lo elseif nv > it.hi then nv = it.hi end
  M.v[it.key] = nv
end

-- text shown in the settings list
function M.label(it)
  local v = M.v[it.key]
  if it.key == "MARGIN" then return v .. " PX" end
  if it.key == "CRASH_DELAY" then return math.floor(v / 10) .. "." .. (v % 10) .. " S" end
  if it.key == "HAPTIC" then return v == 1 and "ON" or "OFF" end
  return tostring(v)
end

function M.radius() return 4 + M.v.MARGIN end

-- difficulty key, e.g. m2d3s3a2c2t40
function M.hash()
  local v = M.v
  return "m" .. v.MARGIN .. "d" .. v.CRASH_DELAY .. "s" .. v.SPEED .. "a" .. v.SPEED_ACCEL
    .. "c" .. v.CURVE_ACCEL .. "t" .. v.TRACK_LEN
end

-- apply "KEY=value" lines; invalid or out-of-range lines are ignored
function M.parse(text)
  for k, val in string.gmatch(text, "([%u_]+)=(%-?%d+)") do
    local it = M.item(k)
    local n = tonumber(val)
    if it and n and n >= it.lo and n <= it.hi and (n - it.lo) % (it.step or 1) == 0 then M.v[k] = n end
  end
end

function M.load()
  M.defaults()
  local f = io.open(M.FILE, "r")
  if not f then return end
  local text = io.read(f, 512)
  io.close(f)
  if text then M.parse(text) end
end

-- returns false when the file can't be written (missing GATERUSH/ folder)
function M.save()
  local f = io.open(M.FILE, "w")
  if not f then return false end
  for i = 1, #M.ITEMS do
    local k = M.ITEMS[i].key
    io.write(f, k, "=", M.v[k], "\n")
  end
  io.close(f)
  return true
end

return M
end)()

local stats = (function()
-- Best/average time per difficulty key, persisted as "key best count avg_ms" lines.
local M = {}

M.FILE = "/SCRIPTS/TOOLS/GATERUSH/gaterush.dat"
M.rec = {} -- key -> { best_ms, count, avg_ms }

function M.parse(text)
  for k, b, c, a in string.gmatch(text, "(%w+) (%d+) (%d+) (%d+)") do
    M.rec[k] = { tonumber(b), tonumber(c), tonumber(a) }
  end
end

function M.load()
  M.rec = {}
  local f = io.open(M.FILE, "r")
  if not f then return end
  local text = "" -- no table library in EdgeTX tool scripts
  repeat
    local chunk = io.read(f, 256)
    if chunk then text = text .. chunk end
  until not chunk or #chunk < 256
  io.close(f)
  M.parse(text)
end

function M.save()
  local f = io.open(M.FILE, "w")
  if not f then return false end
  for k, r in pairs(M.rec) do
    io.write(f, k, " ", r[1], " ", r[2], " ", r[3], "\n")
  end
  io.close(f)
  return true
end

function M.best(key)
  local r = M.rec[key]
  return r and r[1]
end

function M.avg(key)
  local r = M.rec[key]
  return r and r[3]
end

-- record a finished run; returns true when it is a new best
function M.add(key, ms)
  ms = math.floor(ms)
  local r = M.rec[key]
  if not r then
    M.rec[key] = { ms, 1, ms }
    return true
  end
  local isBest = ms > r[1]
  if isBest then r[1] = ms end
  r[3] = math.floor((r[3] * r[2] + ms) / (r[2] + 1) + 0.5)
  r[2] = r[2] + 1
  return isBest
end

function M.reset(key) M.rec[key] = nil end

-- "m:ss" or "--:--"
function M.fmt(ms)
  if not ms then return "--:--" end
  local s = math.floor(ms / 1000)
  local ss = s % 60
  return math.floor(s / 60) .. ":" .. (ss < 10 and "0" or "") .. ss
end

return M
end)()

local draw = (function()
-- Drawing primitives built only from the B&W lcd.* calls (no circles, no bitmaps).
local M = {}

-- glyph bitmaps (rows) -> flat rect lists {x, y, w, h, ...}: one rect per run, runs merged downwards
-- (string.sub, not row:sub: EdgeTX does not set the string metatable)
local function rects(rows, scale)
  local out, open = {}, {} -- open[x0 * 16 + x1] = top row of a run still growing downwards
  local sub = string.sub
  for y = 1, #rows + 1 do
    local row, runs = rows[y] or "", {}
    local x = 1
    while x <= #row do
      if sub(row, x, x) == "1" then
        local x2 = x
        while sub(row, x2 + 1, x2 + 1) == "1" do x2 = x2 + 1 end
        runs[x * 16 + x2] = true
        x = x2 + 1
      else
        x = x + 1
      end
    end
    for key, top in pairs(open) do
      if not runs[key] then
        local x0, x1 = math.floor(key / 16), key % 16
        local n = #out
        out[n + 1], out[n + 2], out[n + 3], out[n + 4] = (x0 - 1) * scale, top * scale, (x1 - x0 + 1) * scale,
          (y - 1 - top) * scale
        open[key] = nil
      end
    end
    for key in pairs(runs) do
      if not open[key] then open[key] = y - 1 end
    end
  end
  return out
end
M.rects = rects

-- 3x5 HUD font (from the mockup renderer)
local F3 = {
  ["0"] = { "111", "101", "101", "101", "111" }, ["1"] = { "010", "110", "010", "010", "111" },
  ["2"] = { "111", "001", "111", "100", "111" }, ["3"] = { "111", "001", "111", "001", "111" },
  ["4"] = { "101", "101", "111", "001", "001" }, ["5"] = { "111", "100", "111", "001", "111" },
  ["6"] = { "111", "100", "111", "101", "111" }, ["7"] = { "111", "001", "001", "001", "001" },
  ["8"] = { "111", "101", "111", "101", "111" }, ["9"] = { "111", "101", "111", "001", "111" },
  [":"] = { "000", "010", "000", "010", "000" },
}
M.small = {}
for k, rows in pairs(F3) do M.small[k] = rects(rows, 1) end
M.digit3 = {}
for d = 0, 9 do M.digit3[d] = M.small[tostring(d)] end

-- countdown digits: the 3x5 font drawn x4 (12x20)
M.big = {}
for d = 1, 3 do M.big[d] = rects(F3[tostring(d)], 4) end

function M.glyph(r, x, y, flags)
  for i = 1, #r, 4 do
    lcd.drawFilledRectangle(x + r[i], y + r[i + 1], r[i + 2], r[i + 3], flags or FORCE)
  end
end

-- quad sprite: disc r=4 with the X erased (sprite #1); crash: ring with a black X
local DISC = { -4, -1, 9, 3, -3, -3, 7, 2, -3, 2, 7, 2, -1, -4, 3, 1, -1, 4, 3, 1 }
function M.quad(x, y, crash)
  local f = crash and ERASE or FORCE
  for i = 1, #DISC, 4 do
    lcd.drawFilledRectangle(x + DISC[i], y + DISC[i + 1], DISC[i + 2], DISC[i + 3], f)
  end
  if not crash then
    lcd.drawLine(x - 3, y - 3, x + 3, y + 3, SOLID, ERASE)
    lcd.drawLine(x - 3, y + 3, x + 3, y - 3, SOLID, ERASE)
    lcd.drawPoint(x, y, FORCE)
    return
  end
  lcd.drawLine(x + 4, y - 1, x + 4, y + 1, SOLID, FORCE)
  lcd.drawLine(x - 4, y - 1, x - 4, y + 1, SOLID, FORCE)
  lcd.drawLine(x - 1, y - 4, x + 1, y - 4, SOLID, FORCE)
  lcd.drawLine(x - 1, y + 4, x + 1, y + 4, SOLID, FORCE)
  lcd.drawLine(x + 4, y + 1, x + 1, y + 4, SOLID, FORCE)
  lcd.drawLine(x - 4, y + 1, x - 1, y + 4, SOLID, FORCE)
  lcd.drawLine(x + 4, y - 1, x + 1, y - 4, SOLID, FORCE)
  lcd.drawLine(x - 4, y - 1, x - 1, y - 4, SOLID, FORCE)
  lcd.drawPoint(x + 3, y + 3, FORCE)
  lcd.drawPoint(x - 3, y + 3, FORCE)
  lcd.drawPoint(x + 3, y - 3, FORCE)
  lcd.drawPoint(x - 3, y - 3, FORCE)
  lcd.drawLine(x - 2, y - 2, x + 2, y + 2, SOLID, FORCE)
  lcd.drawLine(x - 2, y + 2, x + 2, y - 2, SOLID, FORCE)
  lcd.drawPoint(x, y, ERASE)
end

-- 11x11 quad silhouette for the title
function M.quadIcon(x, y)
  lcd.drawFilledRectangle(x - 1, y - 1, 3, 3, FORCE)
  for sx = -1, 1, 2 do
    for sy = -1, 1, 2 do
      lcd.drawLine(x + 2 * sx, y + 2 * sy, x + 4 * sx, y + 4 * sy, SOLID, FORCE)
      local cx, cy = x + 5 * sx, y + 5 * sy
      lcd.drawPoint(cx - 1, cy, FORCE)
      lcd.drawPoint(cx + 1, cy, FORCE)
      lcd.drawPoint(cx, cy - 1, FORCE)
      lcd.drawPoint(cx, cy + 1, FORCE)
    end
  end
end

-- line pattern by tail age: solid, 50 %, 25 %, 12 %
M.PAT = { [0] = SOLID, 0x55, 0x11, 0x01 }

-- drawLine that never sends an off-screen or negative endpoint (the firmware drops those lines)
function M.line(x1, y1, x2, y2, pat)
  if x1 < 0 or y1 < 0 or x2 < 0 or y2 < 0 or x1 >= LCD_W or x2 >= LCD_W or y1 >= LCD_H or y2 >= LCD_H then
    return false
  end
  lcd.drawLine(x1, y1, x2, y2, pat, FORCE)
  return true
end

return M
end)()

local input = (function()
-- Stick reading: STICK_MODE mapping and full travel -> usable area of each half.
local M = {}

-- {left X, left Y, right X, right Y} per stick mode 1..4
M.MAP = {
  { "rud", "ele", "ail", "thr" },
  { "rud", "thr", "ail", "ele" },
  { "ail", "thr", "rud", "ele" },
  { "ail", "ele", "rud", "thr" },
}

M.raw = { 0, 0, 0, 0 } -- -1024..1024, same order as MAP
M.lo, M.hi = 8, 55

-- usable area [RT+2, 63-RT-2]; call again whenever MARGIN changes
function M.setRange(rt)
  M.lo = rt + 2
  M.hi = 63 - rt - 2
end

-- stick value -> half-local coordinate; Y is inverted (stick up = screen up)
function M.pos(v, invert)
  if invert then v = -v end
  return M.lo + (v + 1024) * (M.hi - M.lo) / 2048
end

function M.read(mode)
  local map = M.MAP[mode] or M.MAP[2]
  local raw = M.raw
  for i = 1, 4 do
    local v = getValue(map[i]) or 0
    if v > 1024 then v = 1024 elseif v < -1024 then v = -1024 end
    raw[i] = v
  end
  M.lx, M.ly = M.pos(raw[1]), M.pos(raw[2], true)
  M.rx, M.ry = M.pos(raw[3]), M.pos(raw[4], true)
end

-- side 1 = left, 2 = right: both axes within +-8 %
function M.centered(side)
  local a, b = M.raw[side * 2 - 1], M.raw[side * 2]
  return a <= 82 and a >= -82 and b <= 82 and b >= -82
end

return M
end)()

local track = (function()
-- Tunnel: ring buffer of centerline points, head generator, tail fade, outline, distance.

local M = {}

M.FADE = 9 -- points behind the tail that fade out (3 per dither age)
M.CAP = 80 + M.FADE + 1
M.STEP_PX = 4 -- target spacing of outline vertices
M.MAXV = 45 -- max outline vertices per tunnel (2 lines each)

local cos, sin, floor = math.cos, math.sin, math.floor

-- semicircle offsets for the rounded ends (-90..+90 deg around the heading)
local CA, SA = {}, {}
for i = 0, 8 do
  CA[i] = cos(-math.pi / 2 + i * math.pi / 8)
  SA[i] = sin(-math.pi / 2 + i * math.pi / 8)
end

function M.new()
  local T = { x = {}, y = {}, c = {}, s = {} }
  for i = 1, M.CAP do T.x[i], T.y[i], T.c[i], T.s[i] = 0, 0, 1, 0 end
  return T
end

-- Park-Miller generator, one per tunnel
local function rnd(T)
  T.seed = (T.seed * 16807) % 2147483647
  return T.seed / 2147483647
end
M.rnd = rnd

local function put(T, x, y, h)
  T.head = T.head + 1
  local i = (T.head - 1) % M.CAP + 1
  T.x[i], T.y[i], T.c[i], T.s[i] = x, y, cos(h), sin(h)
  T.hx, T.hy, T.h = x, y, h
end

-- spawn at (x, y): the tail stays here until the tunnel reaches len points
function M.reset(T, x, y, seed, len)
  T.seed = seed % 2147483646 + 1
  T.len = len
  T.head = 0
  T.k = 0
  T.near = 1
  put(T, x, y, rnd(T) * 2 * math.pi)
end

function M.tail(T)
  local t = T.head - T.len + 1
  return t < 1 and 1 or t
end

-- advance the head by v px; kmax = max curvature (1/px); rmin = min turn radius used near walls
function M.step(T, v, kmax, lo, hi, rmin)
  local x, y, h = T.hx, T.hy, T.h
  local k = T.k * 0.85 + (rnd(T) * 2 - 1) * kmax * 0.6
  local ch, sh = cos(h), sin(h)
  local ahead = rmin + 4
  local fx, fy = x + ch * ahead, y + sh * ahead
  if fx < lo or fx > hi or fy < lo or fy > hi then
    -- about to hit the wall: turn hard toward the middle of the area
    local mid = (lo + hi) / 2
    k = (ch * (mid - y) - sh * (mid - x)) >= 0 and 1 / rmin or -1 / rmin
  elseif k > kmax then k = kmax
  elseif k < -kmax then k = -kmax
  end
  T.k = k
  h = h + k * v
  if h > math.pi then h = h - 2 * math.pi elseif h < -math.pi then h = h + 2 * math.pi end
  x, y = x + cos(h) * v, y + sin(h) * v
  if x < lo then x = lo elseif x > hi then x = hi end
  if y < lo then y = lo elseif y > hi then y = hi end
  put(T, x, y, h)
end

-- age of point n: 0 solid, 1..3 fading
local function age(n, tail)
  if n >= tail then return 0 end
  return 1 + floor((tail - 1 - n) / 3)
end

local function cap(T, i, xo, rt, dir, pat)
  local x, y = T.x[i] + xo, T.y[i]
  local c, s = T.c[i] * dir, T.s[i] * dir
  local px, py
  for a = 0, 8 do
    local ox, oy = rt * (c * CA[a] - s * SA[a]), rt * (s * CA[a] + c * SA[a])
    local nx, ny = floor(x + ox + 0.5), floor(y + oy + 0.5)
    if px then draw.line(px, py, nx, ny, pat) end
    px, py = nx, ny
  end
end

-- outline: two offset polylines + rounded ends, fading behind the tail
function M.draw(T, xo, rt, v)
  local tail = M.tail(T)
  local first = tail - M.FADE
  if first < 1 then first = 1 end
  -- ~4 px between vertices, but never more than MAXV vertices (draw-call budget at high speed)
  local stride = floor(M.STEP_PX / v + 0.5)
  local need = math.ceil((T.head - first + 1) / M.MAXV)
  if stride < need then stride = need end
  if stride < 1 then stride = 1 end
  local CAP, X, Y, C, S = M.CAP, T.x, T.y, T.c, T.s
  local lx, ly, rx, ry, pa
  for n = first, T.head do
    if n == first or n == T.head or n % stride == 0 then
      local i = (n - 1) % CAP + 1
      local x, y, ox, oy = X[i] + xo, Y[i], -S[i] * rt, C[i] * rt
      local nlx, nly = floor(x + ox + 0.5), floor(y + oy + 0.5)
      local nrx, nry = floor(x - ox + 0.5), floor(y - oy + 0.5)
      if lx then
        local pat = draw.PAT[pa]
        draw.line(lx, ly, nlx, nly, pat)
        draw.line(rx, ry, nrx, nry, pat)
      end
      lx, ly, rx, ry, pa = nlx, nly, nrx, nry, age(n, tail)
    end
  end
  cap(T, (T.head - 1) % CAP + 1, xo, rt, 1, SOLID)
  local fa = age(first, tail)
  if fa < 4 then cap(T, (first - 1) % CAP + 1, xo, rt, -1, draw.PAT[fa]) end
end

-- squared distance from (qx, qy) to segment n -> n+1; returns d2 and the unclamped projection t
local function seg(T, n, qx, qy)
  local CAP = M.CAP
  local i, j = (n - 1) % CAP + 1, n % CAP + 1
  local ax, ay = T.x[i], T.y[i]
  local dx, dy = T.x[j] - ax, T.y[j] - ay
  local l2 = dx * dx + dy * dy
  local t = 0
  if l2 > 0 then t = ((qx - ax) * dx + (qy - ay) * dy) / l2 end
  local tc = t < 0 and 0 or (t > 1 and 1 or t)
  local ex, ey = ax + dx * tc - qx, ay + dy * tc - qy
  return ex * ex + ey * ey, t
end

local function scan(T, a, b, qx, qy)
  local best, bn, bt = 1e9, a, 0
  for n = a, b do
    local d2, t = seg(T, n, qx, qy)
    if d2 < best then best, bn, bt = d2, n, t end
  end
  return best, bn, bt
end

-- distance check against the solid part (tail..head)
-- returns d2 and true when the tail has just passed the quad (behind the tail point, near it)
function M.near(T, qx, qy, rt2)
  local tail, head = M.tail(T), T.head
  if head == tail then
    local i = (head - 1) % M.CAP + 1
    local ex, ey = T.x[i] - qx, T.y[i] - qy
    return ex * ex + ey * ey, false
  end
  local a, b = T.near - 12, T.near + 12
  if a < tail then a = tail end
  if b > head - 1 then b = head - 1 end
  local d2, n, t
  if a <= b then d2, n, t = scan(T, a, b, qx, qy) end
  -- full scan when the window says "out" or its best is on a window edge (the quad may be past it)
  if not d2 or d2 > rt2 or (n == a and a > tail) or (n == b and b < head - 1) then
    d2, n, t = scan(T, tail, head - 1, qx, qy)
  end
  T.near = n
  -- "tail" only while the quad is still within the rounded end it just slipped off
  return d2, n == tail and t < 0 and d2 <= rt2
end

return M
end)()

local fx = (function()
-- Feedback (tone/haptic with cooldown) and the dust ahead of the tunnel head.
local M = {}

M.cool = 0 -- ticks until the next out-alarm may play
M.haptic = true

function M.tick()
  if M.cool > 0 then M.cool = M.cool - 1 end
end

-- out of the tunnel: 300 Hz / 50 ms + 40 ms vibration, at most every 250 ms
function M.alarm()
  if M.cool > 0 then return end
  playTone(300, 50, 0, PLAY_NOW)
  if M.haptic then playHaptic(40, 0, PLAY_NOW) end
  M.cool = 5
end

function M.beep(freq, ms)
  playTone(freq, ms, 0, PLAY_NOW)
end

-- 5 specks 1..5 px beyond the head cap, re-scattered every frame
local seed = 1
function M.dust(x, y, c, s, rt, xo, xmax)
  for _ = 1, 5 do
    seed = (seed * 16807) % 2147483647
    local d = rt + 1 + seed % 5
    local a = (seed % 19 - 9) / 10 -- -0.9..0.9 rad
    local ca, sa = math.cos(a), math.sin(a)
    local px = math.floor(x + (c * ca - s * sa) * d + 0.5)
    local py = math.floor(y + (s * ca + c * sa) * d + 0.5)
    if px >= 0 and px <= xmax and py >= 0 and py < LCD_H then lcd.drawPoint(px + xo, py, FORCE) end
  end
end

function M.reseed(n) seed = n % 2147483646 + 1 end

return M
end)()

local game = (function()
-- PLAY: two tunnels, two quads, out/tolerance rule, difficulty ramp, HUD.

local M = {}

M.K0 = 1 / 16 -- max curvature at the start (1/px)
M.PROTECT = 30 -- ticks after GO without "out" (1.5 s)
M.CAUSE = { "LEFT HAND", "RIGHT HAND", "TAIL" }

M.tracks = { track.new(), track.new() }
M.qx, M.qy = { 32, 32 }, { 32, 32 }
M.outN = { 0, 0 }
M.outTail = { false, false }

local XO = { 0, 65 } -- screen x offset of each half
local floor = math.floor

-- new run: tunnels at the center of each half, a few straight points ahead
function M.spawn(seed)
  local v = config.v
  M.rt = config.radius()
  M.rt2 = M.rt * M.rt
  M.limit = floor(v.CRASH_DELAY * 2 + 0.5) -- tenths of s -> 50 ms ticks
  if M.limit < 1 then M.limit = 1 end
  M.v0 = config.SPEEDS[v.SPEED]
  M.sa = config.ACCELS[v.SPEED_ACCEL + 1] / 100
  M.ca = config.ACCELS[v.CURVE_ACCEL + 1] / 100
  M.t = 0
  M.v = M.v0
  M.crashed = nil
  M.second = -1
  fx.cool = 0
  fx.haptic = v.HAPTIC == 1
  local mid = (input.lo + input.hi) / 2
  for side = 1, 2 do
    local T = M.tracks[side]
    track.reset(T, mid, mid, seed + side * 1000003, v.TRACK_LEN)
    for _ = 1, 5 do track.step(T, M.v0, 0, input.lo, input.hi, M.rt + 3) end
    M.outN[side] = 0
    M.outTail[side] = false
  end
end

function M.moveQuads()
  M.qx[1], M.qy[1], M.qx[2], M.qy[2] = input.lx, input.ly, input.rx, input.ry
end

-- one 50 ms simulation step
function M.tick()
  M.t = M.t + 1
  fx.tick()
  local tmin = M.t / 1200
  local v = M.v0 * (1 + M.sa * tmin)
  local ramp = M.t / (2 * M.PROTECT) -- straight at GO, full curvature after 3 s
  if ramp > 1 then ramp = 1 end
  local rmin = M.rt + 3
  local kmax = M.K0 * (1 + M.ca * tmin) * ramp
  if kmax > 1 / rmin then kmax = 1 / rmin end
  M.kmax = kmax
  M.v = v
  local anyOut = false
  for side = 1, 2 do
    local T = M.tracks[side]
    track.step(T, v, kmax, input.lo, input.hi, rmin)
    local d2, behind = track.near(T, M.qx[side], M.qy[side], M.rt2)
    if M.t > M.PROTECT and (behind or d2 > M.rt2) then
      -- the cause is fixed when the out-episode starts (the tail passing the quad)
      if M.outN[side] == 0 then M.outTail[side] = behind end
      M.outN[side] = M.outN[side] + 1
      anyOut = true
      if M.outN[side] >= M.limit and not M.crashed then
        M.crashed = M.outTail[side] and 3 or side
      end
    else
      M.outN[side] = 0
    end
  end
  if anyOut then fx.alarm() else fx.cool = 0 end
end

function M.ms() return M.t * 50 end

-- m:ss in the 3x5 font; digits are recomputed only when the second changes
local function timer()
  local s = floor(M.t / 20)
  if s ~= M.second then
    M.second = s
    M.m, M.s10, M.s1 = floor(s / 60), floor(s % 60 / 10), s % 10
  end
  local x = 2
  if M.m >= 10 then
    draw.glyph(draw.digit3[floor(M.m / 10) % 10], x, 2)
    x = x + 4
  end
  draw.glyph(draw.digit3[M.m % 10], x, 2)
  draw.glyph(draw.small[":"], x + 4, 2)
  draw.glyph(draw.digit3[M.s10], x + 8, 2)
  draw.glyph(draw.digit3[M.s1], x + 12, 2)
end

function M.drawWorld()
  lcd.drawLine(64, 0, 64, 63, SOLID, FORCE)
  local rt = M.rt
  for side = 1, 2 do
    local T, xo = M.tracks[side], XO[side]
    track.draw(T, xo, rt, M.v)
    fx.dust(T.hx, T.hy, math.cos(T.h), math.sin(T.h), rt, xo, side == 1 and 63 or 62)
  end
end

-- out quads blink between the crash and the normal sprite every 2 frames
function M.drawQuads(frame)
  for side = 1, 2 do
    local out = M.outN[side] > 0
    draw.quad(floor(M.qx[side] + 0.5) + XO[side], floor(M.qy[side] + 0.5), out and frame % 4 < 2)
  end
end

function M.drawHud()
  timer()
  lcd.drawText(2, 56, "L", 0)
  lcd.drawText(121, 56, "R", 0)
  local n = M.outN[1] > M.outN[2] and M.outN[1] or M.outN[2]
  if n > 0 and M.limit > 1 then
    lcd.drawRectangle(2, 8, 30, 3, FORCE)
    local w = floor(30 * (M.limit - n) / M.limit + 0.5)
    if w > 0 then lcd.drawFilledRectangle(2, 8, w, 3, FORCE) end
  end
  if M.outN[1] > 0 then lcd.drawFilledRectangle(0, 54, 9, 10) end
  if M.outN[2] > 0 then lcd.drawFilledRectangle(119, 54, 9, 10) end
end

return M
end)()

local screens = (function()
-- Static screens: WARN, TITLE, SETTINGS, CENTER, countdown box, PAUSE, CRASHED.

local M = {}

function M.center(y, s, flags)
  lcd.drawText(64, y, s, (flags or 0) + CENTER)
end

-- text in reverse video: draw it centered, then XOR a box around it
local function boxed(y, s)
  M.center(y + 2, s)
  local right = lcd.getLastRightPos()
  local w = 2 * (right - 64) - 1 -- text width (CENTER puts ceil(w/2) right of x=64)
  lcd.drawFilledRectangle(right - w - 2, y, w + 3, 11)
end

local function rule() lcd.drawLine(8, 18, 119, 18, DOTTED, FORCE) end

function M.warn(modelName)
  M.center(2, "RF WARNING", DBLSIZE)
  rule()
  M.center(22, "RADIO KEEPS SENDING")
  M.center(31, "STICKS TO " .. (modelName or "YOUR MODEL"))
  M.center(40, "DISARM / POWER OFF")
  boxed(51, "[ENT] I KNOW")
end

function M.title(best, saveOk)
  M.center(3, "GATERUSH", DBLSIZE)
  M.center(21, saveOk and "TWIN-STICK FPV" or "NO SAVE")
  draw.quadIcon(27, 37)
  draw.quadIcon(100, 37)
  M.center(34, "BEST " .. best)
  M.center(46, "ENT:ARM  RTN:EXIT")
  M.center(56, "HOLD ENT: SETTINGS")
end

M.MENU = {} -- config items + RESET BEST + EXIT
for i = 1, #config.ITEMS do M.MENU[i] = config.ITEMS[i] end
M.MENU[#M.MENU + 1] = { name = "RESET BEST", action = "reset" }
M.MENU[#M.MENU + 1] = { name = "EXIT", action = "exit" }

function M.settings(sel, editing, confirm)
  local page = sel <= 5 and 1 or 2
  lcd.drawText(2, 1, "SETTINGS", 0)
  lcd.drawText(90, 1, page .. "/2", 0)
  lcd.drawLine(0, 9, 127, 9, SOLID, FORCE)
  for row = 1, 5 do
    local i = (page - 1) * 5 + row
    local it, y = M.MENU[i], 2 + row * 10
    local val = ""
    if it.key then val = config.label(it)
    elseif it.action == "reset" then val = confirm and "ENT?" or "..." end
    if i == sel and editing then val = "<" .. val .. ">" end
    lcd.drawText(4, y, it.name, 0)
    lcd.drawText(84, y, val, 0)
    if i == sel then lcd.drawFilledRectangle(0, y - 1, 124, 9) end
  end
  lcd.drawLine(126, 11, 126, 62, SOLID, FORCE)
  lcd.drawFilledRectangle(125, page == 1 and 11 or 37, 3, 26, FORCE)
end

-- 21x21 box with crosshair and the stick dot, hold bar below
local function stickbox(cx, cy, sx, sy, hold)
  lcd.drawRectangle(cx - 10, cy - 10, 21, 21, FORCE)
  lcd.drawLine(cx - 8, cy, cx + 8, cy, DOTTED, FORCE)
  lcd.drawLine(cx, cy - 8, cx, cy + 8, DOTTED, FORCE)
  local dx, dy = math.floor(sx * 8 / 1024 + 0.5), math.floor(-sy * 8 / 1024 + 0.5)
  lcd.drawFilledRectangle(cx + dx - 1, cy + dy - 1, 3, 3, FORCE)
  lcd.drawRectangle(cx - 11, 52, 22, 3, FORCE)
  local w = math.floor(22 * hold + 0.5)
  if w > 0 then lcd.drawFilledRectangle(cx - 11, 52, w, 3, FORCE) end
end

function M.centerSticks(holdL, holdR)
  lcd.drawLine(64, 0, 64, 63, SOLID, FORCE)
  lcd.drawText(10, 4, "CENTER", 0)
  lcd.drawText(75, 4, "CENTER", 0)
  lcd.drawText(10, 12, "STICKS", 0)
  lcd.drawText(75, 12, "STICKS", 0)
  local r = input.raw
  stickbox(32, 38, r[1], r[2], holdL)
  stickbox(97, 38, r[3], r[4], holdR)
end

-- "3" "2" "1" in an 18x24 box per half, above or below the quad so it never hides it
function M.count(n, qy)
  for side = 1, 2 do
    local x = side == 1 and 23 or 88
    local y = qy[side] > 32 and 3 or 38
    lcd.drawFilledRectangle(x, y, 18, 24, ERASE)
    lcd.drawRectangle(x, y, 18, 24, FORCE)
    draw.glyph(draw.big[n], x + 3, y + 2)
  end
end

function M.pause()
  lcd.drawFilledRectangle(14, 20, 100, 24, ERASE)
  lcd.drawRectangle(14, 20, 100, 24, FORCE)
  lcd.drawRectangle(16, 22, 96, 20, FORCE)
  M.center(24, "PAUSED")
  M.center(34, "ENT:GO RTN:QUIT")
end

-- c = { time, cause, best, avg, newBest }
function M.crashed(c)
  M.center(2, "CRASHED", DBLSIZE)
  rule()
  M.center(22, c.line1)
  M.center(32, c.line2)
  if c.newBest then boxed(42, "NEW BEST!") end
  M.center(56, "[ENT] RE-ARM")
end

return M
end)()

-- GateRush entry: state machine, fixed 50 ms timestep, events, backlight.

local WARN, TITLE, SETTINGS, CENTER, COUNTDOWN, PLAY, PAUSE, RESUME, CRASHED = 1, 2, 3, 4, 5, 6, 7, 8, 9

local state, last, acc, frame = WARN, 0, 0, 0
local ignoreUntil = 0
local eatEnter = false -- the ENTER release that follows a long press
local saveOk, modelName, best = true, nil, "--:--"
local sel, editing, confirm = 1, false, false
local hold = { 0, 0 }
local count = 0 -- countdown ticks
local flash = 0
local crash = {}

-- events (virtual + legacy; some constants are nil on some radios)
local function is(e, a, b, c, d)
  return e ~= 0 and (e == a or e == b or e == c or e == d)
end
local function isEnter(e) return is(e, EVT_VIRTUAL_ENTER, EVT_ENTER_BREAK, EVT_ROT_BREAK) end
local function isLong(e) return is(e, EVT_VIRTUAL_ENTER_LONG, EVT_ENTER_LONG, EVT_ROT_LONG) end
local function isExit(e) return is(e, EVT_VIRTUAL_EXIT, EVT_EXIT_BREAK) end
-- encoder, +/- keys or PAGE keys
local function isNext(e)
  return is(e, EVT_VIRTUAL_NEXT, EVT_VIRTUAL_INC_REPT, EVT_VIRTUAL_NEXT_PAGE, EVT_PLUS_BREAK)
end
local function isPrev(e)
  return is(e, EVT_VIRTUAL_PREV, EVT_VIRTUAL_DEC_REPT, EVT_VIRTUAL_PREV_PAGE, EVT_MINUS_BREAK)
end

local function refreshBest()
  best = stats.fmt(stats.best(config.hash()))
end

local function go(s)
  state = s
  ignoreUntil = getTime() + 30
  if s == TITLE then refreshBest() end
  if s == CENTER then hold[1], hold[2] = 0, 0 end
  if s == COUNTDOWN then
    game.spawn(getTime())
    count = 0
  end
  if s == RESUME then count = 0 end
end

local function finish(quit)
  local key = config.hash()
  local ms = game.ms()
  local newBest = false
  if not quit then
    newBest = stats.add(key, ms)
    stats.save()
  end
  local cause = quit and "QUIT" or game.CAUSE[game.crashed]
  local line1 = "TIME " .. stats.fmt(ms) .. "  " .. cause
  if #line1 > 21 then line1 = "TIME " .. stats.fmt(ms) .. " " .. cause end
  crash.line1 = line1
  crash.line2 = "BEST " .. stats.fmt(stats.best(key)) .. "  AVG " .. stats.fmt(stats.avg(key))
  crash.newBest = newBest
  flash = quit and 0 or 2
  go(CRASHED)
end

local function leaveSettings()
  saveOk = config.save()
  input.setRange(config.radius())
  editing, confirm = false, false
  go(TITLE)
end

local function settingsEvent(e)
  local it = screens.MENU[sel]
  if editing then
    if isNext(e) then config.change(it, 1)
    elseif isPrev(e) then config.change(it, -1)
    elseif isEnter(e) or isExit(e) then editing = false end
    return
  end
  if isNext(e) then sel = sel % #screens.MENU + 1; confirm = false
  elseif isPrev(e) then sel = (sel - 2) % #screens.MENU + 1; confirm = false
  elseif isExit(e) then leaveSettings()
  elseif isEnter(e) then
    if it.key then editing = true
    elseif it.action == "exit" then leaveSettings()
    elseif confirm then
      stats.reset(config.hash())
      stats.save()
      confirm = false
    else confirm = true end
  end
end

-- countdown of 60 ticks with a beep per second; returns true when done
local function countdown(steps)
  for _ = 1, steps do
    if count % 20 == 0 then fx.beep(count < 60 and 600 or 1200, count < 60 and 80 or 250) end
    count = count + 1
    if count > 60 then return true end
  end
  return false
end

local function update(e, steps)
  if state == WARN then
    if isEnter(e) then go(TITLE) elseif isExit(e) then return 1 end
  elseif state == TITLE then
    if isLong(e) then
      killEvents(e)
      eatEnter = true
      sel, editing, confirm = 1, false, false
      go(SETTINGS)
    elseif isEnter(e) then go(CENTER)
    elseif isExit(e) then return 1 end
  elseif state == SETTINGS then
    settingsEvent(e)
    refreshBest()
  elseif state == CENTER then
    if isExit(e) then go(TITLE) return 0 end
    for side = 1, 2 do
      hold[side] = input.centered(side) and hold[side] + steps or 0
      if hold[side] > 10 then hold[side] = 10 end
    end
    if hold[1] >= 10 and hold[2] >= 10 then go(COUNTDOWN) end
  elseif state == COUNTDOWN or state == RESUME then
    game.moveQuads()
    if isExit(e) then
      if state == COUNTDOWN then go(TITLE) else go(PAUSE) end
    elseif countdown(steps) then
      state = PLAY
    end
  elseif state == PLAY then
    if isExit(e) then go(PAUSE) return 0 end
    game.moveQuads()
    for _ = 1, steps do
      game.tick()
      if game.crashed then finish(false) break end
    end
  elseif state == PAUSE then
    if isEnter(e) then go(RESUME) elseif isExit(e) then finish(true) end
  elseif state == CRASHED then
    if isEnter(e) then go(CENTER) elseif isExit(e) then go(TITLE) end
  end
  return 0
end

local function render()
  lcd.clear()
  if state == WARN then screens.warn(modelName)
  elseif state == TITLE then screens.title(best, saveOk)
  elseif state == SETTINGS then screens.settings(sel, editing, confirm)
  elseif state == CENTER then screens.centerSticks(hold[1] / 10, hold[2] / 10)
  elseif state == CRASHED and flash == 0 then screens.crashed(crash)
  else
    game.drawWorld()
    if state == COUNTDOWN or state == RESUME then
      local n = 3 - math.floor(count / 20)
      screens.count(n < 1 and 1 or n, game.qy)
    end
    game.drawQuads(frame)
    if state ~= COUNTDOWN then game.drawHud() end
    if state == PAUSE then screens.pause()
    elseif state == CRASHED then
      lcd.drawFilledRectangle(0, 0, LCD_W, LCD_H) -- invert flash
      flash = flash - 1
    end
  end
end

local function init()
  config.load()
  saveOk = config.save()
  stats.load()
  input.setRange(config.radius())
  if model and model.getInfo then
    local ok, info = pcall(model.getInfo)
    if ok and info and info.name and info.name ~= "" then modelName = string.upper(string.sub(info.name, 1, 11)) end
  end
  refreshBest()
  last = getTime()
  ignoreUntil = last + 40
end

local function run(event)
  local now = getTime()
  acc = acc + now - last
  last = now
  if acc > 20 then acc = 20 end
  local steps = math.floor(acc / 5)
  acc = acc - steps * 5
  frame = frame + 1
  event = event or 0
  if eatEnter and isEnter(event) then
    eatEnter = false
    event = 0
  end
  if now < ignoreUntil then event = 0 end
  input.read(config.v.STICK_MODE)
  local r = update(event, steps)
  if state >= CENTER and state ~= PAUSE and state ~= CRASHED then lcd.resetBacklightTimeout() end
  render()
  return r
end

return { init = init, run = run }
